import { z } from "zod";
import { NamedColors, CatColors } from "./TxtWidget.mjs";
import { MarkDownContent } from "../other.mjs";
const zLatLng = z.object({ lat: z.number(), lng: z.number() });
const zCoord = zLatLng.or(z.string().trim().min(2));
